import * as THREE from "three";

/**
 * A single authored cross-section of one anatomical mass.
 *
 * Sections are authored in world space. The surface is generated by sweeping a
 * superellipse ring through consecutive section centres, so every mass owns its
 * own profile curve. This is deliberately NOT a single nose-to-tail loft: each
 * part in `dogSkillOnAnatomy.ts` is an independent solid that overlaps its
 * neighbours at a plausible joint.
 */
export type Section = {
  /** Ring centre in world space. */
  at: readonly [number, number, number];
  /** Half extent across the ring's lateral axis. */
  halfWidth: number;
  /** Half extent across the ring's in-plane vertical axis. */
  halfHeight: number;
  /** Superellipse exponent. 2 = ellipse, >2 = boxier plane breaks, <2 = pinched. */
  roundness?: number;
  /** Narrows the lower half laterally (rib keel, brisket). */
  lowerWidthScale?: number;
  /** Lifts the lower half (belly tuck). */
  lowerHeightScale?: number;
};

export type SectionSolidOptions = {
  /** Radial samples per ring. Low counts keep the faceted low-poly read. */
  segments?: number;
  /**
   * Reference axis used to derive each ring frame. Use [0,0,1] for parts whose
   * sweep direction is close to vertical (limbs, ears) so the frame stays stable.
   */
  axisUp?: readonly [number, number, number];
  capStart?: boolean;
  capEnd?: boolean;
};

const DEFAULT_SEGMENTS = 12;
const DEFAULT_AXIS_UP = [0, 1, 0] as const;
const FALLBACK_AXES = [
  new THREE.Vector3(0, 0, 1),
  new THREE.Vector3(1, 0, 0),
  new THREE.Vector3(0, 1, 0),
];

function superellipse(theta: number, roundness: number): [number, number] {
  const exponent = 2 / roundness;
  const c = Math.cos(theta);
  const s = Math.sin(theta);
  return [
    Math.sign(c) * Math.abs(c) ** exponent,
    Math.sign(s) * Math.abs(s) ** exponent,
  ];
}

function frameFor(
  centers: THREE.Vector3[],
  index: number,
  axisUp: THREE.Vector3,
): { right: THREE.Vector3; up: THREE.Vector3 } {
  const prev = centers[Math.max(0, index - 1)];
  const next = centers[Math.min(centers.length - 1, index + 1)];
  const tangent = next.clone().sub(prev);
  if (tangent.lengthSq() < 1e-10) {
    tangent.set(0, 1, 0);
  }
  tangent.normalize();

  let right = new THREE.Vector3().crossVectors(axisUp, tangent);
  for (const fallback of FALLBACK_AXES) {
    if (right.lengthSq() > 1e-6) break;
    right = new THREE.Vector3().crossVectors(fallback, tangent);
  }
  right.normalize();

  const up = new THREE.Vector3().crossVectors(tangent, right).normalize();
  return { right, up };
}

function ringPoints(
  section: Section,
  center: THREE.Vector3,
  right: THREE.Vector3,
  up: THREE.Vector3,
  segments: number,
): THREE.Vector3[] {
  const roundness = section.roundness ?? 2.4;
  const lowerWidthScale = section.lowerWidthScale ?? 1;
  const lowerHeightScale = section.lowerHeightScale ?? 1;
  const points: THREE.Vector3[] = [];

  for (let k = 0; k < segments; k += 1) {
    const theta = (k / segments) * Math.PI * 2;
    let [u, v] = superellipse(theta, roundness);
    if (v < 0) {
      u *= lowerWidthScale;
      v *= lowerHeightScale;
    }
    points.push(
      center
        .clone()
        .addScaledVector(right, u * section.halfWidth)
        .addScaledVector(up, v * section.halfHeight),
    );
  }

  return points;
}

/**
 * Builds a flat-shaded, non-indexed solid from an authored section stack.
 * Winding is outward so `computeVertexNormals` yields usable facet normals.
 */
export function buildSectionSolid(
  sections: readonly Section[],
  options: SectionSolidOptions = {},
): THREE.BufferGeometry {
  const segments = options.segments ?? DEFAULT_SEGMENTS;
  const axisUp = new THREE.Vector3(...(options.axisUp ?? DEFAULT_AXIS_UP));
  const capStart = options.capStart ?? true;
  const capEnd = options.capEnd ?? true;

  const centers = sections.map((section) => new THREE.Vector3(...section.at));
  const rings = sections.map((section, index) => {
    const { right, up } = frameFor(centers, index, axisUp);
    return ringPoints(section, centers[index], right, up, segments);
  });

  const positions: number[] = [];
  const pushTriangle = (a: THREE.Vector3, b: THREE.Vector3, c: THREE.Vector3) => {
    positions.push(a.x, a.y, a.z, b.x, b.y, b.z, c.x, c.y, c.z);
  };

  for (let i = 0; i < rings.length - 1; i += 1) {
    const lower = rings[i];
    const upper = rings[i + 1];
    for (let k = 0; k < segments; k += 1) {
      const next = (k + 1) % segments;
      pushTriangle(lower[k], lower[next], upper[next]);
      pushTriangle(lower[k], upper[next], upper[k]);
    }
  }

  if (capStart) {
    const ring = rings[0];
    const center = centers[0];
    for (let k = 0; k < segments; k += 1) {
      const next = (k + 1) % segments;
      pushTriangle(center, ring[next], ring[k]);
    }
  }

  if (capEnd) {
    const last = rings.length - 1;
    const ring = rings[last];
    const center = centers[last];
    for (let k = 0; k < segments; k += 1) {
      const next = (k + 1) % segments;
      pushTriangle(center, ring[k], ring[next]);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(positions, 3),
  );
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
}

/** Mirrors an authored section stack across the sagittal plane. */
export function mirrorSections(sections: readonly Section[]): Section[] {
  return sections.map((section) => ({
    ...section,
    at: [-section.at[0], section.at[1], section.at[2]] as const,
  }));
}
